/** Every mutation has an explicit one-use confirmation; deferred render always rechecks the current city/window. */
public final class ProductionMenu implements Listener {
    private final JavaPlugin plugin;private final ProductionService service;
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm 'МСК'").withZone(ZoneId.of("Europe/Moscow"));
    private static final class View implements InventoryHolder{final UUID owner,city;final Map<Integer,Runnable> actions=new HashMap<>();Inventory inventory;View(UUID owner,UUID city){this.owner=owner;this.city=city;}public Inventory getInventory(){return inventory;}}
    public ProductionMenu(JavaPlugin plugin,ProductionService service){this.plugin=plugin;this.service=service;plugin.getServer().getPluginManager().registerEvents(this,plugin);}
    private View view(Player p,String title){UUID city=service.city(p);var v=new View(p.getUniqueId(),city);v.inventory=MenuStyle.inventory(plugin,v,54,title);button(v,22,Material.CLOCK,"Загружаем каталог",List.of("Сохранённые партии не изменяются"),null);button(v,49,Material.BARRIER,"Закрыть",List.of(),p::closeInventory);p.openInventory(v.inventory);return v;}
    private boolean current(Player p,View v){try{return p.isOnline()&&p.getUniqueId().equals(v.owner)&&service.city(p).equals(v.city)&&p.getOpenInventory().getTopInventory()==v.inventory;}catch(Exception e){return false;}}
    private static String error(Throwable e){while(e.getCause()!=null&&(e instanceof CompletionException||e instanceof java.lang.reflect.InvocationTargetException))e=e.getCause();return e.getMessage()==null?"Операция недоступна":e.getMessage();}
    private static Material icon(String name){Material m=Material.matchMaterial(name);return m!=null&&m.isItem()?m:Material.PAPER;}
    private static String state(String value){return switch(value){case "PLANNING"->"Смета ожидает подтверждения склада";case "OPEN"->"Сбор материалов или партий";case "FINISHING"->"Выпуск ожидает сверки";case "CANCELLING"->"Отмена ожидает сверки";case "ISSUED"->"Партии учтены в городском каталоге";case "CANCELLED"->"Отменено без потери резерва";case "COMPLETED"->"Совместный результат сохранён";default->value;};}
    private void button(View v,int slot,Material icon,String name,List<String> lore,Runnable action){var item=new ItemStack(icon);var meta=item.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("§b"+name));meta.setLore(MenuStyle.loreStrings(lore.stream().map(s->"§7"+s).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);v.inventory.setItem(slot,item);if(action!=null)v.actions.put(slot,action);else v.actions.remove(slot);}
    private <T>void load(Player p,View v,CompletionStage<T> future,Consumer<T> draw){future.whenComplete((result,failure)->{if(!plugin.isEnabled())return;SuiteScheduler.entity(plugin,p,()->{if(!current(p,v))return;v.inventory.clear();v.actions.clear();button(v,49,Material.BARRIER,"Закрыть",List.of(),p::closeInventory);if(failure!=null){button(v,22,Material.BARRIER,"Раздел временно недоступен",List.of(error(failure),"Сохранённые квитанции и партии остаются в каталоге"),null);button(v,45,Material.ARROW,"К каталогу",List.of(),()->home(p));return;}try{draw.accept(result);}catch(Exception e){button(v,22,Material.BARRIER,"Действие недоступно",List.of(error(e)),null);}});});}
    public void home(Player p){home(p,1);}
    private void home(Player p,int page){var v=view(p,"Производственные партии • "+page);load(p,v,service.repository().stock(v.city,page),rows->{int slot=0;for(var row:rows)button(v,slot++,Material.CHEST,row.title(),List.of("Свободно: "+row.available(),"В резервах: "+row.reserved(),"Выпущено городом: "+row.produced(),"Получено обменом: "+row.received(),"Передано обменом: "+row.sent(),"Партии учитываются в каталоге города.","Предмет в личный инвентарь не выдаётся."),null);if(rows.isEmpty())button(v,22,Material.BOOK,"Пока нет готовых партий",List.of("Откройте производство и обеспечьте смету.","Для выпуска нужно уникальное здание III уровня."),null);button(v,40,Material.KNOWLEDGE_BOOK,"Для чего нужны партии",List.of("Это готовая продукция направления города.","Она учитывается здесь и используется", "в совместных проектах разных городов.","Материалы каждой партии списываются один раз."),null);button(v,45,Material.ARROW,"К специализации",List.of(),()->p.performCommand("town specialization"));button(v,46,Material.CRAFTING_TABLE,"Начать производство",List.of("Рецепт и отдельное подтверждение"),()->recipes(p));button(v,47,Material.FURNACE,"Мои производственные сметы",List.of("Материалы, выпуск, сверка и отмена"),()->batches(p,1));button(v,51,Material.BEACON,"Совместные проекты",List.of("Общие результаты разных направлений"),()->projects(p,1));button(v,53,Material.WRITABLE_BOOK,"История города",List.of("Квитанции партий и резервов"),()->history(p,1));if(page>1)button(v,48,Material.ARROW,"Предыдущие партии",List.of(),()->home(p,page-1));if(rows.size()==20)button(v,50,Material.ARROW,"Следующие партии",List.of(),()->home(p,page+1));});}
    public void recipes(Player p){var v=view(p,"Рецепты производственных партий");v.inventory.clear();var catalog=service.catalog();int slot=0;for(var recipe:catalog.products().values().stream().sorted(Comparator.comparing(ProductionCatalog.Product::id)).toList())button(v,slot++,icon(recipe.icon()),recipe.title(),List.of("Направление: "+service.profileTitle(recipe.profile()),"Материалов в рецепте: "+recipe.materials().size(),"Нажмите: полный рецепт и подтверждение"),()->start(p,recipe.id(),1));button(v,45,Material.ARROW,"К каталогу",List.of(),()->home(p));}
    public void start(Player p,String product,int amount){var catalog=service.catalog();var recipe=catalog.products().get(product);if(recipe==null)throw new IllegalArgumentException("Неизвестная партия");UUID town=service.city(p);service.authorize(p,town,recipe.profile(),true);UUID request=UUID.randomUUID();var lines=new ArrayList<String>();lines.add(recipe.title()+" × "+amount);lines.add("Материалы передаются через принятые /orders.");lines.add("Излишек останется в серверном запасе.");lines.add("После выпуска партии будут учтены в каталоге.");var view=confirm(p,"Новая производственная смета",lines,()->recipes(p),()->service.create(p,request,town,recipe,amount,catalog),b->batch(p,b.id()));int slot=27;for(var e:new TreeMap<>(recipe.costs(amount)).entrySet()){var material=icon(e.getKey());var item=new ItemStack(material);var meta=item.getItemMeta();meta.displayName(net.kyori.adventure.text.Component.translatable(material.translationKey()));meta.setLore(MenuStyle.loreStrings(List.of("§7Нужно: "+e.getValue())));item.setItemMeta(meta);view.inventory.setItem(slot++,item);}}
    public void batches(Player p,int page){var v=view(p,"Производственные сметы • "+page);load(p,v,service.repository().batches(v.city,page),rows->{int slot=0;for(var b:rows)button(v,slot++,Material.FURNACE,b.title()+" × "+b.amount(),List.of(state(b.state()),"ID: "+b.id(),"Нажмите: материалы и действия"),()->batch(p,b.id()));if(page>1)button(v,45,Material.ARROW,"Предыдущая страница",List.of(),()->batches(p,page-1));else button(v,45,Material.ARROW,"К каталогу",List.of(),()->home(p));if(rows.size()==20)button(v,53,Material.ARROW,"Следующая страница",List.of(),()->batches(p,page+1));});}
    public void batch(Player p,UUID id){var v=view(p,"Смета производственной партии");load(p,v,service.repository().batch(id),b->{if(b==null||!b.town().equals(v.city))throw new IllegalArgumentException("Это не смета вашего города");int slot=0;for(var e:new TreeMap<>(b.materials()).entrySet()){Material material=icon(e.getKey());var item=new ItemStack(material);var meta=item.getItemMeta();meta.displayName(net.kyori.adventure.text.Component.translatable(material.translationKey()));meta.setLore(MenuStyle.loreStrings(List.of("§7Всего для партии: "+e.getValue())));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);v.inventory.setItem(slot++,item);}button(v,40,Material.BOOK,b.title()+" × "+b.amount(),List.of(state(b.state()),"Материальная смета: "+b.contract(),"Предметы в личный инвентарь не выдаются.","Партии доступны в городском каталоге."),null);button(v,45,Material.ARROW,"К сметам",List.of(),()->batches(p,1));button(v,46,Material.CHEST,"Передать материалы заказа",List.of("Для любого жителя своего города","Используется обычная награда и лимит /orders"),()->orders(p,b));button(v,47,Material.LIME_DYE,"Выпустить партии",List.of("Для мэра: сначала будут проверены", "полная смета и работа уникального здания"),()->confirm(p,"Подтвердить выпуск",List.of(b.title()+" × "+b.amount(),"Вся смета материалов будет использована.","Готовые партии появятся в городском каталоге."),()->batch(p,id),()->service.resolve(p,id,"finish"),r->batch(p,id)));button(v,51,Material.SPYGLASS,"Сверить состояние",List.of("Для мэра: проверить квитанцию склада","Не повторяет уже подтверждённый выпуск"),()->run(p,v,service.resolve(p,id,"sync"),r->batch(p,id)));button(v,53,Material.RED_DYE,"Отменить смету",List.of("Для мэра: неиспользованный резерв", "вернётся в запас сервера.","Награды сданных заказов сохраняются."),()->confirm(p,"Отмена сметы партии",List.of("Материалы вернутся в серверный запас.","Личные награды заказов не отнимаются.","Готовый выпуск отменить нельзя."),()->batch(p,id),()->service.resolve(p,id,"cancel"),r->batch(p,id)));if(Set.of("ISSUED","CANCELLED").contains(b.state()))for(int closedSlot:List.of(46,47,53))button(v,closedSlot,Material.GRAY_DYE,"Смета закрыта",List.of(state(b.state()),"Новые материалы и изменения не принимаются."),null);});}
    private void orders(Player p,Batch batch){var v=view(p,"Поставки для производства");v.inventory.clear();int slot=0;for(var order:service.orders(p)){UUID id=UUID.fromString((String)order.get("id"));String title=(String)order.get("title");button(v,slot++,Material.CHEST,title,List.of("Предметов: "+order.get("goal"),"Награда заказа и лимиты не меняются.","Нажмите: подтвердить обычную сдачу"),()->confirm(p,"Передать заказ в смету",List.of(title,"Списываются обычные материалы заказа.","Недостающие попадут в смету партии.","Излишек останется на серверном складе.","Если смета уже закрыта, вся поставка","пополнит серверный запас; награда сохранится."),()->orders(p,batch),()->service.deliver(p,id,batch),r->batch(p,batch.id())));}if(slot==0)button(v,22,Material.BOOK,"Нет принятых заказов доставки",List.of("Примите подходящий заказ через /orders."),null);button(v,45,Material.ARROW,"К смете",List.of(),()->batch(p,batch.id()));button(v,49,Material.CHEST,"Открыть /orders",List.of(),()->p.performCommand("orders"));}
    public void projects(Player p,int page){var v=view(p,"Совместные проекты • "+page);load(p,v,service.repository().projects(page),rows->{int slot=0;for(var row:rows)button(v,slot++,row.state().equals("COMPLETED")?Material.NETHER_STAR:Material.BEACON,row.title(),List.of(state(row.state()),"Направлений и городов: от "+row.minimumCities(),row.result()),()->project(p,row.id()));button(v,45,Material.ARROW,page>1?"Предыдущая страница":"К каталогу",List.of(),page>1?()->projects(p,page-1):()->home(p));button(v,47,Material.CRAFTING_TABLE,"Начать совместный проект",List.of("Для мэра своего города"),()->projectRecipes(p));if(rows.size()==20)button(v,53,Material.ARROW,"Следующая страница",List.of(),()->projects(p,page+1));});}
    private void projectRecipes(Player p){var v=view(p,"Общие цели городов");v.inventory.clear();var catalog=service.catalog();int slot=0;for(var goal:catalog.projects().values().stream().sorted(Comparator.comparing(ProductionCatalog.Joint::id)).toList())button(v,slot++,Material.BEACON,goal.title(),List.of(goal.result(),"Разных городов и направлений: "+goal.minimumCities(),"Нажмите: смета и подтверждение"),()->{UUID id=UUID.randomUUID();var lines=new ArrayList<String>();lines.add(goal.result());goal.goods().forEach((key,count)->lines.add(catalog.products().get(key).title()+" × "+count));lines.add("Денежной награды и новых бонусов нет.");confirm(p,"Начать совместный проект",lines,()->projectRecipes(p),()->service.createProject(p,id,v.city,goal,catalog),r->project(p,id));});button(v,45,Material.ARROW,"К проектам",List.of(),()->projects(p,1));}
    public void project(Player p,UUID id){var v=view(p,"Общий проект городов");load(p,v,service.repository().joint(id),row->{int slot=0;for(var e:new TreeMap<>(row.project().goods()).entrySet())button(v,slot++,Material.CHEST,productName(e.getKey()),List.of("Нужно партий: "+e.getValue(),(row.project().state().equals("OPEN")?"В резерве: ":row.project().state().equals("COMPLETED")?"Использовано: ":"Возвращено: ")+row.supplied().getOrDefault(e.getKey(),0L),"Направление поставщика: "+service.profileTitle(row.project().profiles().get(e.getKey()))),null);button(v,40,row.project().state().equals("COMPLETED")?Material.NETHER_STAR:Material.BOOK,row.project().title(),List.of(state(row.project().state()),row.project().result(),"Участвует городов: "+row.members().size(),"Разных направлений: "+new HashSet<>(row.members().values()).size(),"Требуется городов и направлений: "+row.project().minimumCities(),"Памятный результат, без выдачи денег или бонусов."),null);button(v,45,Material.ARROW,"К общим проектам",List.of(),()->projects(p,1));button(v,46,Material.CHEST,"Внести партии своего города",List.of("Для мэра: партии будут зарезервированы", "до завершения или отмены проекта"),()->contributions(p,row));button(v,47,Material.WRITABLE_BOOK,"Города и квитанции",List.of("Кто передал партии и сколько"),()->contributors(p,row,0));button(v,51,Material.LIME_DYE,"Завершить общий проект",List.of("Для мэра города-организатора","Все зарезервированные партии будут использованы"),()->confirm(p,"Завершить совместный проект",List.of(row.project().result(),"Резерв партий будет использован.","Результат останется в истории участвующих городов."),()->project(p,id),()->service.finishProject(p,id,false),r->project(p,id)));button(v,53,Material.RED_DYE,"Отменить общий проект",List.of("Для мэра города-организатора","Каждый город получит свои партии обратно"),()->confirm(p,"Отменить совместный проект",List.of("Все партии вернутся в каталоги своих городов.","Готовый совместный результат не отменяется."),()->project(p,id),()->service.finishProject(p,id,true),r->project(p,id)));if(!row.project().state().equals("OPEN"))for(int closedSlot:List.of(46,51,53))button(v,closedSlot,Material.GRAY_DYE,"Проект закрыт",List.of(state(row.project().state()),"Условия и квитанции доступны для просмотра."),null);});}
    private static String cityName(String id){try{var town=com.palmergames.bukkit.towny.TownyAPI.getInstance().getTown(UUID.fromString(id));return town==null?"Удалённый город":town.getName();}catch(Exception e){return "Неизвестный город";}}
    private String productName(String key){try{var p=service.catalog().products().get(key);return p==null?key:p.title();}catch(Exception ignored){return key;}}
    private void contributions(Player p,JointView project){contributions(p,project,1);}
    private void contributions(Player p,JointView project,int page){var v=view(p,"Вклад города • "+page);load(p,v,service.repository().stock(v.city,page),rows->{var actor=service.authorize(p,v.city,null,false);int slot=0;for(var stock:rows){long missing=project.project().goods().getOrDefault(stock.product(),0L)-project.supplied().getOrDefault(stock.product(),0L);int amount=(int)Math.min(64,Math.min(missing,stock.available()));if(amount<=0||!actor.profile().equals(stock.profile()))continue;UUID receipt=UUID.randomUUID();button(v,slot++,Material.CHEST,stock.title(),List.of("Передать в резерв: "+amount,"Из свободных партий вашего города","Нажмите: отдельное подтверждение"),()->confirm(p,"Подтвердить вклад города",List.of(stock.title()+" × "+amount,"Партии нельзя использовать в другом проекте.","При отмене они вернутся вашему городу."),()->project(p,project.project().id()),()->service.contribute(p,receipt,project.project().id(),v.city,stock.product(),amount),r->project(p,project.project().id())));}if(slot==0)button(v,22,Material.BOOK,"Подходящих свободных партий нет",List.of("Нужны партии текущего направления города", "из незакрытой сметы этого проекта."),null);button(v,45,Material.ARROW,"К проекту",List.of(),()->project(p,project.project().id()));if(page>1)button(v,48,Material.ARROW,"Предыдущие партии",List.of(),()->contributions(p,project,page-1));if(rows.size()==20)button(v,50,Material.ARROW,"Следующие партии",List.of(),()->contributions(p,project,page+1));});}
    private void contributors(Player p,JointView row,int page){var v=view(p,"Квитанции общего проекта");v.inventory.clear();int slot=0;for(var c:row.contributions().stream().skip(page*36L).limit(36).toList())button(v,slot++,Material.PAPER,productName((String)c.get("product"))+" × "+c.get("amount"),List.of("Город: "+cityName((String)c.get("town")),"Передал: "+c.get("actor"),DATE.format(Instant.ofEpochMilli(((Number)c.get("at")).longValue())),"Квитанция: "+c.get("receipt")),null);button(v,45,Material.ARROW,page>0?"Предыдущая страница":"К проекту",List.of(),page>0?()->contributors(p,row,page-1):()->project(p,row.project().id()));if((page+1L)*36<row.contributions().size())button(v,53,Material.ARROW,"Следующая страница",List.of(),()->contributors(p,row,page+1));}
    private static String historyName(String kind){return switch(kind){case "batch-plan"->"Подготовлена производственная смета";case "batch-issued"->"Производственные партии выпущены";case "batch-cancelled"->"Смета производства отменена";case "FINISHING"->"Выпуск ожидает подтверждения";case "CANCELLING"->"Отмена ожидает подтверждения";case "joint-plan"->"Начат совместный проект";case "joint-contribution"->"Партии переданы в резерв";case "joint-completed"->"Совместный проект завершён";case "joint-cancelled"->"Совместный проект отменён";default->"Операция производственного каталога";};}
    private void history(Player p,int page){var v=view(p,"История производственных партий");load(p,v,service.repository().history(v.city,page),rows->{int slot=0;for(var row:rows)button(v,slot++,Material.PAPER,historyName((String)row.get("kind")),List.of((String)row.get("reason"),"Инициатор: "+row.get("actor"),DATE.format(Instant.ofEpochMilli(((Number)row.get("at")).longValue())),"Операция: "+row.get("operation")),null);button(v,45,Material.ARROW,page>1?"Предыдущая страница":"К каталогу",List.of(),page>1?()->history(p,page-1):()->home(p));if(rows.size()==20)button(v,53,Material.ARROW,"Следующая страница",List.of(),()->history(p,page+1));});}
    private <T>View confirm(Player p,String title,List<String> lines,Runnable back,Supplier<CompletionStage<T>> action,Consumer<T> next){var v=view(p,title);v.inventory.clear();button(v,13,Material.BOOK,title,lines,null);button(v,20,Material.LIME_DYE,"Подтвердить",List.of("Один раз; дождитесь сохранения результата"),()->{if(v.actions.remove(20)==null)return;button(v,20,Material.CLOCK,"Сохраняем решение",List.of("Не повторяйте действие до ответа"),null);try{run(p,v,action.get(),next);}catch(Exception e){p.sendMessage("§e"+error(e));back.run();}});button(v,24,Material.ARROW,"Вернуться",List.of("Без изменений"),back);return v;}
    private <T>void run(Player p,View v,CompletionStage<T> future,Consumer<T> next){future.whenComplete((result,failure)->{if(!plugin.isEnabled())return;SuiteScheduler.entity(plugin,p,()->{if(!current(p,v))return;if(failure!=null){p.sendMessage("§e"+error(failure));button(v,20,Material.BARRIER,"Нужна проверка",List.of(error(failure),"Откройте смету и сверьте состояние"),null);}else{try{if(!service.city(p).equals(v.city))throw new IllegalArgumentException("Город изменился");next.accept(result);}catch(Exception lost){p.closeInventory();}}});});}
    @EventHandler public void click(InventoryClickEvent e){if(!(e.getView().getTopInventory().getHolder() instanceof View v))return;e.setCancelled(true);if(!(e.getWhoClicked() instanceof Player p)||!current(p,v)||e.getClick()!=ClickType.LEFT)return;var action=v.actions.get(e.getRawSlot());if(action!=null)SuiteScheduler.entity(plugin,p,()->{if(!current(p,v))return;try{action.run();}catch(Exception failure){p.sendMessage("§e"+error(failure));}});}
    @EventHandler public void drag(InventoryDragEvent e){if(e.getView().getTopInventory().getHolder() instanceof View)e.setCancelled(true);}
    public void close(){SuiteScheduler.cleanupPlayers(plugin,p->{if(p.getOpenInventory().getTopInventory().getHolder() instanceof View)p.closeInventory();});}
}
